1	//! Residue persistence — matrix-shaped residues.csv (NKP coupling source).
2	
3	use anyhow::{bail, Result};
4	use std::path::Path;
5	
6	use crate::structure::analysis::residues::Residue;
7	
8	pub fn load(residual_dir: &Path) -> Result<Vec<Residue>> {
9	    crate::storage::format::read_residues(residual_dir)
10	}
11	
12	/// Upsert by (force_id, component_id); keeps matrix writes idempotent (A-04).
13	pub fn append(residual_dir: &Path, residue: Residue) -> Result<()> {
14	    let mut all = load(residual_dir)?;
15	    if let Some(existing) = all
16	        .iter_mut()
17	        .find(|r| r.force_id == residue.force_id && r.component_id == residue.component_id)
18	    {
19	        existing.status = "1".into();
20	        existing.notes.clear();
21	        if existing.id.is_empty() {
22	            existing.id = residue.id;
23	        }
24	    } else {
25	        all.push(residue);
26	    }
27	    crate::storage::format::write_residues(residual_dir, &all)
28	}
29	
30	pub fn next_id(residues: &[Residue]) -> String {
31	    let max = residues
32	        .iter()
33	        .filter_map(|r| {
34	            r.id.strip_prefix("R-")
35	                .or_else(|| r.id.strip_prefix('R'))
36	                .and_then(|n| n.parse::<u32>().ok())
37	        })
38	        .max()
39	        .unwrap_or(0);
40	    format!("R-{:02}", max + 1)
41	}
42	
43	pub fn force_exists(residual_dir: &Path, force_id: &str) -> Result<bool> {
44	    if crate::storage::stressors::load(residual_dir)?
45	        .iter()
46	        .any(|s| s.id == force_id)
47	    {
48	        return Ok(true);
49	    }
50	    if crate::storage::purposes::load(residual_dir)?
51	        .iter()
52	        .any(|p| p.id == force_id)
53	    {
54	        return Ok(true);
55	    }
56	    Ok(false)
57	}
58	
59	pub fn append_whole_system(
60	    residual_dir: &Path,
61	    force_id: &str,
62	    notes: &str,
63	) -> Result<String> {
64	    if notes.trim().is_empty() {
65	        bail!("--whole-system requires --notes describing the hardware, process, organization, or policy zig");
66	    }
67	    if !force_exists(residual_dir, force_id)? {
68	        bail!("force id '{}' not found in stressors or purposes", force_id);
69	    }
70	    merge_force_notes(residual_dir, force_id, notes)?;
71	    let existing = load(residual_dir)?;
72	    let id = next_id(&existing);
73	    append(
74	        residual_dir,
75	        Residue::whole_system(id.clone(), force_id, notes),
76	    )?;
77	    Ok(id)
78	}
79	
80	fn merge_force_notes(residual_dir: &Path, force_id: &str, notes: &str) -> Result<()> {
81	    let note = notes.trim();
82	    if note.is_empty() {
83	        return Ok(());
84	    }
85	    if let Ok(mut stressors) = crate::storage::stressors::load(residual_dir) {
86	        if let Some(s) = stressors.iter_mut().find(|s| s.id == force_id) {
87	            if !s.naive_change.contains(note) {
88	                if !s.naive_change.is_empty() {
89	                    s.naive_change.push(' ');
90	                }
91	                s.naive_change.push_str(note);
92	            }
93	            return crate::storage::stressors::write_all_pub(residual_dir, &stressors);
94	        }
95	    }
96	    if let Ok(mut purposes) = crate::storage::purposes::load(residual_dir) {
97	        if let Some(p) = purposes.iter_mut().find(|p| p.id == force_id) {
98	            if !p.naive_change.contains(note) {
99	                if !p.naive_change.is_empty() {
100	                    p.naive_change.push(' ');
101	                }
102	                p.naive_change.push_str(note);
103	            }
104	            return crate::storage::purposes::write_all_pub(residual_dir, &purposes);
105	        }
106	    }
107	    Ok(())
108	}
109	
110	/// Clear a force×component matrix cell (remove residue coupling).
111	pub fn remove_coupling(
112	    residual_dir: &Path,
113	    force_id: &str,
114	    component_id: &str,
115	) -> Result<()> {
116	    let mut all = load(residual_dir)?;
117	    all.retain(|r| {
118	        !(r.force_id == force_id && r.component_id == component_id && r.is_coupled())
119	    });
120	    crate::storage::format::write_residues(residual_dir, &all)
121	}
122	
123	/// Repoint coupling from one component column to another atomically.
124	pub fn move_coupling(
125	    residual_dir: &Path,
126	    force_id: &str,
127	    from_component: &str,
128	    to_component: &str,
129	) -> Result<()> {
130	    let mut all = load(residual_dir)?;
131	    all.retain(|r| !(r.force_id == force_id && r.component_id == from_component));
132	    if let Some(existing) = all
133	        .iter_mut()
134	        .find(|r| r.force_id == force_id && r.component_id == to_component)
135	    {
136	        existing.status = "1".into();
137	        existing.notes.clear();
138	    } else {
139	        let id = next_id(&all);
140	        all.push(Residue::coupling(id, force_id, to_component));
141	    }
142	    crate::storage::format::write_residues(residual_dir, &all)
143	}
