152	    fn seed_matrix(residual: &Path) {
153	        std::fs::create_dir_all(residual).unwrap();
154	        std::fs::write(
155	            residual.join("stressors.csv"),
156	            "id,shortname,description,naive_change,outcomes,attractor_id\n\
157	S-01,alpha,desc,change,outcome,A-01\n",
158	        )
159	        .unwrap();
160	        std::fs::write(
161	            residual.join("components.csv"),
162	            "name,description,status,architecture_set\n\
163	auth,Auth module,actual,set\n\
164	db,Database,actual,set\n",
165	        )
166	        .unwrap();
167	        format::write_residues(
168	            residual,
169	            &[
170	                Residue::coupling("R-01", "S-01", "auth"),
171	                Residue::coupling("R-02", "S-01", "db"),
172	            ],
173	        )
174	        .unwrap();
175	    }
