177	    #[test]
178	    fn remove_coupling_clears_matrix_cell() {
179	        let dir = tempdir().unwrap();
180	        let residual = dir.path().join("residual");
181	        seed_matrix(&residual);
182	
183	        remove_coupling(&residual, "S-01", "auth").unwrap();
184	
185	        let residues = load(&residual).unwrap();
186	        assert!(
187	            !residues
188	                .iter()
189	                .any(|r| r.force_id == "S-01" && r.component_id == "auth" && r.is_coupled()),
190	            "auth coupling for S-01 must be cleared"
191	        );
192	        assert!(
193	            residues
194	                .iter()
195	                .any(|r| r.force_id == "S-01" && r.component_id == "db" && r.is_coupled()),
196	            "db coupling for S-01 must remain"
197	        );
198	    }
