200	    #[test]
201	    fn move_coupling_repoints_atomically() {
202	        let dir = tempdir().unwrap();
203	        let residual = dir.path().join("residual");
204	        seed_matrix(&residual);
205	
206	        move_coupling(&residual, "S-01", "auth", "db").unwrap();
207	
208	        let residues = load(&residual).unwrap();
209	        assert!(
210	            !residues
211	                .iter()
212	                .any(|r| r.force_id == "S-01" && r.component_id == "auth" && r.is_coupled()),
213	            "auth coupling must be cleared after move"
214	        );
215	        let db_coupled = residues
216	            .iter()
217	            .filter(|r| r.force_id == "S-01" && r.component_id == "db" && r.is_coupled())
218	            .count();
219	        assert_eq!(db_coupled, 1, "db must have exactly one coupling after move");
220	    }
221	}
