18	
19	pub fn load(residual_dir: &Path) -> Result<Vec<Stressor>> {
20	    let path = residual_dir.join("stressors.csv");
21	    if !path.exists() {
22	        return Ok(vec![]);
23	    }
24	    let mut rdr = csv::ReaderBuilder::new()
25	        .has_headers(true)
26	        .from_path(&path)?;
27	    let mut result = Vec::new();
28	    for record in rdr.deserialize() {
29	        let s: Stressor = record?;
30	        result.push(s);
31	    }
32	    Ok(result)
33	}
