35	pub fn append(residual_dir: &Path, stressor: Stressor) -> Result<()> {
36	    let mut all = load(residual_dir)?;
37	    if all.iter().any(|s| s.id == stressor.id) {
38	        anyhow::bail!("stressor id '{}' already exists", stressor.id);
39	    }
40	    all.push(stressor);
41	    write_all(residual_dir, &all)
42	}
