48	fn write_all(residual_dir: &Path, rows: &[Stressor]) -> Result<()> {
49	    let mut buf = format!("{HEADER}\n");
50	    for s in rows {
51	        let mut row = Vec::new();
52	        {
53	            let mut wtr = csv::WriterBuilder::new().has_headers(false).from_writer(&mut row);
54	            wtr.write_record(&[
55	                &s.id,
56	                &s.shortname,
57	                &s.description,
58	                &s.naive_change,
59	                &s.outcomes,
60	                &s.attractor_id,
61	            ])?;
62	            wtr.flush()?;
63	        }
64	        buf.push_str(std::str::from_utf8(&row)?);
65	    }
66	    std::fs::write(residual_dir.join("stressors.csv"), buf)?;
67	    Ok(())
68	}
