1	//! Component registry mutations — append, idempotent add, residues.csv column extension.
2	
3	use anyhow::Result;
4	use std::path::Path;
5	
6	use crate::structure::definition::components::Component;
7	
8	const HEADER: &str = "name,description,status,architecture_set";
9	
10	fn write_all(residual_dir: &Path, rows: &[Component]) -> Result<()> {
11	    let mut buf = format!("{HEADER}\n");
12	    for c in rows {
13	        let mut row = Vec::new();
14	        {
15	            let mut wtr = csv::WriterBuilder::new().has_headers(false).from_writer(&mut row);
16	            wtr.write_record(&[
17	                &c.name,
18	                &c.description,
19	                &c.status,
20	                &c.architecture_set,
21	            ])?;
22	            wtr.flush()?;
23	        }
24	        buf.push_str(std::str::from_utf8(&row)?);
25	    }
26	    std::fs::write(residual_dir.join("components.csv"), buf)?;
27	    Ok(())
28	}
29	
30	fn extend_residues_header(residual_dir: &Path, component_name: &str) -> Result<()> {
31	    let path = residual_dir.join("residues.csv");
32	    let text = if path.exists() {
33	        std::fs::read_to_string(&path)?
34	    } else {
35	        "force\n".to_string()
36	    };
37	    let ends_with_newline = text.ends_with('\n');
38	    let mut lines: Vec<String> = text.lines().map(String::from).collect();
39	    if lines.is_empty() {
40	        lines.push("force".to_string());
41	    }
42	    let header_parts: Vec<&str> = lines[0].split(',').map(str::trim).collect();
43	    if header_parts.iter().any(|c| *c == component_name) {
44	        return Ok(());
45	    }
46	    lines[0] = format!("{},{}", lines[0].trim_end_matches(','), component_name);
47	    for line in lines.iter_mut().skip(1) {
48	        if !line.trim().is_empty() {
49	            line.push(',');
50	        }
51	    }
52	    let mut out = lines.join("\n");
53	    if ends_with_newline || lines.len() == 1 {
54	        out.push('\n');
55	    }
56	    std::fs::write(path, out)?;
57	    Ok(())
58	}
