60	/// Idempotent append — no-op when component name already exists. No session guard (caller holds session).
61	pub(crate) fn append_idempotent_inner(
62	    residual_dir: &Path,
63	    name: &str,
64	    description: &str,
65	    status: &str,
66	    architecture_set: &str,
67	) -> Result<bool> {
68	    let mut components = load(residual_dir)?;
69	    if components.iter().any(|c| c.name == name) {
70	        return Ok(false);
71	    }
72	    components.push(Component {
73	        name: name.to_string(),
74	        description: description.to_string(),
75	        status: status.to_string(),
76	        architecture_set: architecture_set.to_string(),
77	    });
78	    write_all(residual_dir, &components)?;
79	    extend_residues_header(residual_dir, name)?;
80	    Ok(true)
81	}
