83	/// Append a component to components.csv and extend residues.csv header with its name column.
84	pub fn append(
85	    residual_dir: &Path,
86	    name: &str,
87	    description: &str,
88	    status: &str,
89	    architecture_set: &str,
90	) -> Result<()> {
91	    let session = crate::storage::integrity::sessions::begin_mutation(residual_dir, false)?;
92	    append_idempotent_inner(residual_dir, name, description, status, architecture_set)?;
93	    session.commit()?;
94	    Ok(())
95	}
96	
97	/// Idempotent append — no-op when component name already exists.
98	pub fn append_idempotent(
99	    residual_dir: &Path,
100	    name: &str,
101	    description: &str,
102	    status: &str,
103	    architecture_set: &str,
104	) -> Result<bool> {
105	    let session = crate::storage::integrity::sessions::begin_mutation(residual_dir, false)?;
106	    let added = append_idempotent_inner(residual_dir, name, description, status, architecture_set)?;
107	    session.commit()?;
108	    Ok(added)
109	}
