111	/// Update status for an existing component (e.g. proposed → actual). Errors if name unknown.
112	/// No session guard — caller holds the mutation session.
113	pub(crate) fn set_status_inner(residual_dir: &Path, name: &str, status: &str) -> Result<()> {
114	    let mut components = load(residual_dir)?;
115	    let Some(row) = components.iter_mut().find(|c| c.name == name) else {
116	        anyhow::bail!("unknown component: {name} not found");
117	    };
118	    row.status = status.to_string();
119	    write_all(residual_dir, &components)?;
120	    Ok(())
121	}
122	
123	/// Update status for an existing component (e.g. proposed → actual). Errors if name unknown.
124	/// Session/change-detection guarded like other mutators.
125	pub fn set_status(residual_dir: &Path, name: &str, status: &str) -> Result<()> {
126	    let session = crate::storage::integrity::sessions::begin_mutation(residual_dir, false)?;
127	    set_status_inner(residual_dir, name, status)?;
128	    session.commit()?;
129	    Ok(())
130	}
