224	            } else if whole_system {
225	                let id = residues::append_whole_system(dir, &force_id, &notes)?;
226	                println!("Added whole-system-residue {}", id);
227	            } else {
228	                if component_id.is_empty() {
229	                    anyhow::bail!("provide --component-id or --whole-system");
