282	        }
283	        AddTarget::Attractor {
284	            name,
285	            description,
286	            positive_state,
287	            negative_state,
288	        } => {
289	            let existing = attractors::load(dir)?;
290	            let id = attractors::next_id(&existing);
291	            attractors::append(
292	                dir,
