78	fn parse_persona(content: &str, name: String) -> Persona {
79	    let mut role = String::new();
80	    let mut concerns = String::new();
81	    let mut desires = String::new();
82	    let mut stressor_ids = Vec::new();
83	
84	    // Extract front-matter between --- delimiters
85	    let inner = if content.starts_with("---") {
86	        let after = &content[3..];
87	        if let Some(end) = after.find("---") {
88	            &after[..end]
89	        } else {
90	            ""
91	        }
92	    } else {
93	        ""
94	    };
95	
96	    let mut in_stressor_ids = false;
97	    for line in inner.lines() {
98	        let trimmed = line.trim();
99	        if let Some(rest) = trimmed.strip_prefix("role:") {
100	            role = rest.trim().trim_matches('"').to_string();
101	            in_stressor_ids = false;
102	        } else if let Some(rest) = trimmed.strip_prefix("concerns:") {
103	            concerns = rest.trim().trim_matches('"').to_string();
104	            in_stressor_ids = false;
105	        } else if let Some(rest) = trimmed.strip_prefix("desires:") {
106	            desires = rest.trim().trim_matches('"').to_string();
107	            in_stressor_ids = false;
108	        } else if trimmed.starts_with("stressor_ids:") {
109	            in_stressor_ids = true;
110	        } else if in_stressor_ids && trimmed.starts_with("- ") {
111	            let id = trimmed[2..].trim().trim_matches('"').to_string();
112	            if !id.is_empty() {
113	                stressor_ids.push(id);
114	            }
115	        } else if !trimmed.is_empty() && !trimmed.starts_with('-') {
116	            in_stressor_ids = false;
117	        }
118	    }
119	
120	    Persona { name, role, concerns, desires, stressor_ids }
121	}
