2	
3	use anyhow::{bail, Context, Result};
4	use chrono::{DateTime, Duration, Utc};
5	use std::path::PathBuf;
6	
7	use crate::config::Config;
8	use crate::storage::git_sidecar::SidecarConfig;
9	
10	pub const MARKER_FILE: &str = ".residual-write-authorized";
11	pub const DEFAULT_MINUTES: i64 = 30;
12	
13	pub fn marker_path(cfg: &Config) -> PathBuf {
14	    cfg.config_host_dir.join(MARKER_FILE)
15	}
16	
17	/// Grant local write permission for a bounded period. This marker is deliberately
18	/// not ignored: a staged marker is a leak and the pre-commit hook tells the operator
19	/// to unstage it.
20	pub fn authorize(cfg: &Config, minutes: i64) -> Result<DateTime<Utc>> {
21	    if minutes <= 0 {
22	        bail!("write authorization duration must be positive minutes");
23	    }
24	    std::fs::create_dir_all(&cfg.config_host_dir)
25	        .with_context(|| format!("create {}", cfg.config_host_dir.display()))?;
26	    let expires_at = Utc::now() + Duration::minutes(minutes);
27	    std::fs::write(
28	        marker_path(cfg),
29	        format!("expires_at={}\n", expires_at.to_rfc3339()),
30	    )
31	    .with_context(|| format!("write {}", marker_path(cfg).display()))?;
32	    Ok(expires_at)
33	}
34	
35	/// Require a current authorization only when metadata lives on a sidecar branch.
36	/// Inline ledgers retain their existing direct-CLI workflow.
37	pub fn require(cfg: &Config) -> Result<()> {
38	    let sidecar = SidecarConfig::from_config_file(&cfg.config_path)?;
39	    if !sidecar.enabled {
40	        return Ok(());
41	    }
42	
43	    let path = marker_path(cfg);
44	    let content = std::fs::read_to_string(&path).with_context(|| {
45	        format!(
46	            "residual metadata writes require explicit authorization; run `residual write authorize` before mutating metadata (missing {})",
47	            path.display()
48	        )
49	    })?;
50	    let raw_expiry = content
51	        .lines()
52	        .find_map(|line| line.strip_prefix("expires_at="))
53	        .context("invalid write-authorization marker; rerun `residual write authorize`")?;
54	    let expires_at = DateTime::parse_from_rfc3339(raw_expiry)
55	        .context("invalid write-authorization expiry; rerun `residual write authorize`")?
56	        .with_timezone(&Utc);
57	    if Utc::now() >= expires_at {
58	        bail!(
59	            "residual write authorization expired at {}; run `residual write authorize` again",
60	            expires_at.to_rfc3339()
61	        );
62	    }
63	    Ok(())
64	}
