pub fn update(cfg: &Config, target: UpdateTarget, force: bool) -> Result<()> {
    write_authorization::require(cfg)?;
    let dir = metadata_dir_for_mutation(cfg)?;
    let session = integrity::sessions::begin_mutation(&dir, force)?;
    update_entry(&dir, target)?;
    session.commit()?;
    git_sidecar::persist_if_sidecar(cfg, &dir)?;
    Ok(())
}

fn update_entry(dir: &Path, target: UpdateTarget) -> Result<()> {
    match target {
        UpdateTarget::Stressor {
            force_id,
            description,
            attractor_id,
            naive_change,
            shortname,
            outcomes,
            add_component,
            remove_component,
        } => {
            stressors::update(
                dir,
                &force_id,
                description,
                attractor_id,
                naive_change,
                shortname,
                outcomes,
            )?;
            for component_id in &add_component {
                if !residues::force_exists(dir, &force_id)? {
                    anyhow::bail!("force id '{}' not found in stressors or purposes", force_id);
                }
                let existing = residues::load(dir)?;
                let id = residues::next_id(&existing);
                residues::append(
                    dir,
                    Residue::coupling(id, force_id.clone(), component_id.clone()),
                )?;
            }
            for component_id in &remove_component {
                residues::remove_coupling(dir, &force_id, component_id)?;
            }
            println!("Updated stressor {}", force_id);
        }
        UpdateTarget::Purpose {
            force_id,
            description,
            attractor_id,
            naive_change,
            shortname,
            outcomes,
            add_component,
            remove_component,
        } => {
            purposes::update(
                dir,
                &force_id,
                description,
                attractor_id,
                naive_change,
                shortname,
                outcomes,
            )?;
            for component_id in &add_component {
                if !residues::force_exists(dir, &force_id)? {
                    anyhow::bail!("force id '{}' not found in stressors or purposes", force_id);
                }
                let existing = residues::load(dir)?;
                let id = residues::next_id(&existing);
                residues::append(
                    dir,
                    Residue::coupling(id, force_id.clone(), component_id.clone()),
                )?;
            }
            for component_id in &remove_component {
                residues::remove_coupling(dir, &force_id, component_id)?;
            }
            println!("Updated purpose {}", force_id);
        }
        UpdateTarget::Attractor {
            id,
            name,
            description,
            positive_state,
            negative_state,
        } => {
            attractors::update(dir, &id, name, description, positive_state, negative_state)?;
            println!("Updated attractor {}", id);
        }
        UpdateTarget::Component {
            name,
            description,
            status,
            architecture_set,
        } => {
            components::update(dir, &name, description, status, architecture_set)?;
            println!("Updated component '{}'", name);
        }
        UpdateTarget::Term {
            term,
            definition,
            domain,
            related,
        } => {
            terminology::update(dir, &term, definition, domain, related)?;
            println!("Updated term '{}'", term);
        }
        UpdateTarget::Persona {
            name,
            role,
            concerns,
            desires,
        } => {
            personas::update(dir, &name, role, concerns, desires)?;
            println!("Updated persona '{}'", name);
        }
    }
    Ok(())
}

